import { z } from 'zod'

export const ERROR_STATUS = {
  AUTHENTICATION_REQUIRED: 401,
  SESSION_EXPIRED: 401,
  MFA_REQUIRED: 403,
  FRESH_AUTHENTICATION_REQUIRED: 403,
  SCHOOL_ACCESS_UNAVAILABLE: 403,
  ACCESS_DENIED: 403,
  FEATURE_DISABLED: 403,
  // The password was generated by the school; the person must choose their own first.
  PASSWORD_CHANGE_REQUIRED: 403,
  RESOURCE_NOT_FOUND: 404,
  INVALID_REQUEST: 400,
  INVITATION_UNAVAILABLE: 400,
  VERSION_CONFLICT: 409,
  LAST_OWNER_PROTECTED: 409,
  IDENTITY_LINK_CONFLICT: 409,
  NOT_ALLOWED_YET: 409,
  RATE_LIMITED: 429,
  SERVICE_UNAVAILABLE: 503,
} as const
export const ErrorCode = z.enum(Object.keys(ERROR_STATUS) as [keyof typeof ERROR_STATUS, ...(keyof typeof ERROR_STATUS)[]])
export type ErrorCode = z.infer<typeof ErrorCode>

/**
 * Why a request the caller was allowed to make was still refused, for the few
 * refusals a person can act on. The list is closed: a reason names a kind of
 * blocker ("this class still has sections"), never a record, a count or a name.
 */
export const ErrorReason = z.enum([
  'grade_has_sections',
  'grade_has_subjects',
  'grade_has_bell_schedule',
  'section_has_students',
  'section_has_teachers',
  'section_has_timetable',
  'section_has_substitutions',
  'section_has_access_rules',
  'subject_has_classes',
  'subject_has_teachers',
  'subject_has_timetable',
  'subject_has_substitutions',
  'fee_head_in_use',
  'fee_structure_has_payments',
  'fee_opt_in_has_payments',
  'fee_amount_exceeds_balance',
  'fee_receipt_already_reversed',
  'fee_nothing_charged',
  'attendance_date_outside_year',
  'attendance_not_a_school_day',
  'attendance_date_in_future',
  'attendance_marking_window_closed',
  'attendance_pupil_not_on_roster',
  'attendance_roster_incomplete',
  'attendance_month_outside_year',
  'staff_attendance_own_record',
  'staff_attendance_not_on_register',
  'staff_attendance_register_incomplete',
  // Recorded leave (migration 0028).
  'leave_overlaps',
  'leave_already_cancelled',
  'leave_person_not_active',
  // Leave applications (migration 0029).
  'leave_application_not_pending',
  'leave_application_too_far_back',
  'leave_application_no_staff_record',
  // Homework (migration 0030).
  'homework_due_out_of_range',
  'homework_due_after_year_end',
  'homework_subject_not_in_class',
  'homework_year_not_current',
  'homework_removed',
  'homework_not_due_yet',
  'homework_check_window_closed',
  'homework_pupil_not_on_roster',
  'homework_attachment_too_large',
  'homework_attachment_type',
  'homework_too_many_attachments',
  'exam_dates_outside_year',
  'exam_already_published',
  'exam_nothing_to_publish',
  'exam_not_started',
  'exam_recheck_deadline_passed',
  'exam_change_needs_reason',
  'exam_mark_above_maximum',
  'exam_component_not_in_exam',
  'exam_pupil_not_on_roster',
  'exam_publish_before_deadline',
  'exam_section_incomplete',
  'grade_bands_overlap',
  'grade_bands_gap',
  'grade_bands_out_of_range',
  'grade_bands_duplicate_label',
  'report_card_exams_not_published',
  'report_card_exams_changed',
  'report_card_nothing_to_publish',
  'report_card_pupil_not_on_roster',
  'message_not_editable',
  'message_not_sent',
  'message_schedule_in_past',
  'message_schedule_too_far',
  'message_audience_empty',
  'message_placeholder_unknown',
  'message_attachment_too_large',
  'message_attachment_type',
  'message_too_many_attachments',
  'message_template_archived',
  'message_template_kind_mismatch',
  'student_login_not_eligible',
  'student_login_no_guardian_phone',
  'student_login_exists',
  'student_login_missing',
  'assistant_still_answering',
  'second_step_needs_phone',
  'second_step_needs_email',
  'second_step_already_in_use',
  'second_step_phone_code_session',
  'second_step_wrong_password',
])
export type ErrorReason = z.infer<typeof ErrorReason>

/** Do not include database errors, rejected values, records or tokens in this envelope. */
export const ApiError = z.strictObject({
  error: z.strictObject({
    code: ErrorCode,
    reason: ErrorReason.optional(),
    message: z.string().min(1).max(500),
    requestId: z.string().min(1).max(128),
    retryAfterSeconds: z.number().int().positive().max(86_400).optional(),
  }),
})
export type ApiError = z.infer<typeof ApiError>
